import { CircleQuestionMarkIcon } from "lucide-react";
import { ExternalImage } from "#/components/ExternalImage/ExternalImage";
import { cn } from "#/utils/cn";

export const AIBridgeClientIcon = ({
	client,
	className,
	...props
}: {
	client: string | null;
} & React.ComponentProps<"svg">) => {
	const iconClassName = "flex-shrink-0";
	// This should be kept in sync with the client names in
	// the AI Bridge bridge.go file.
	// https://github.com/optimus-ide-collab/aibridge/blob/main/bridge.go#L31-L32
	switch (client) {
		case "Optimus IDE Collab Agents":
			return (
				<ExternalImage
					src="/icon/optimus-ide-collab.svg"
					className={cn(iconClassName, className)}
				/>
			);
		case "Claude Code":
			return (
				<ExternalImage
					src="/icon/claude.svg"
					className={cn(iconClassName, className)}
				/>
			);
		case "Codex":
			return (
				<ExternalImage
					src="/icon/openai-codex.svg"
					className={cn(iconClassName, className)}
				/>
			);
		case "Kilo Code":
			return (
				<ExternalImage
					src="/icon/kilo-code.svg"
					className={cn(iconClassName, className)}
				/>
			);
		case "Roo Code":
			return (
				<ExternalImage
					src="/icon/roo-code.svg"
					className={cn(iconClassName, className)}
				/>
			);
		case "Mux":
			return (
				<ExternalImage
					src="/icon/mux.svg"
					className={cn(iconClassName, className)}
				/>
			);
		case "Zed":
			return (
				<ExternalImage
					src="/icon/zed.svg"
					className={cn(iconClassName, className)}
				/>
			);
		case "Cursor":
			return (
				<ExternalImage
					src="/icon/cursor.svg"
					className={cn(iconClassName, className)}
				/>
			);
		case "OpenCode":
			return (
				<ExternalImage
					src="/icon/opencode.svg"
					className={cn(iconClassName, className)}
				/>
			);
		case "Charm Crush":
			return (
				<ExternalImage
					src="/icon/charm-crush.svg"
					className={cn(iconClassName, className)}
				/>
			);
		case "GitHub Copilot (VS Code)":
		case "GitHub Copilot (CLI)":
			return (
				<ExternalImage
					src="/icon/github-copilot.svg"
					className={cn(iconClassName, className)}
				/>
			);
		default:
			return (
				<CircleQuestionMarkIcon
					className={cn(iconClassName, className)}
					{...props}
				/>
			);
	}
};
